module zigzag_grey_counter (\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] K,\n    output reg [15:0] result,\n    output reg done\n);\n    localparam [1:0] IDLE      = 2'd0;\n    localparam [1:0] PROCESS   = 2'd1;\n    localparam [1:0] DONE_ST   = 2'd2;\n\n    reg [1:0] state;\n    reg [2:0] current_diag;\n    reg [2:0] current_step;\n    reg [15:0] visit_count;\n    reg [15:0] grey_count;\n    wire [3:0] row, col;\n    wire is_grey;\n    wire [3:0] steps_current_diag;\n    wire even_diag = ~current_diag[0];\n\n    assign steps_current_diag = (current_diag < 3'd4) ? (current_diag + 4'd1) : (4'd7 - current_diag);\n\n    // Row/col calculation\n    reg [3:0] row_calc, col_calc;\n    always @(*) begin\n        if (even_diag) begin\n            row_calc = (current_diag < 3'd4) ? current_step[3:0] : (current_diag - 3'd3) + current_step[2:0];\n            col_calc = current_diag[3:0] - row_calc;\n        end else begin\n            col_calc = (current_diag < 3'd4) ? current_step[3:0] : (current_diag - 3'd3) + current_step[2:0];\n            row_calc = current_diag[3:0] - col_calc;\n        end\n    end\n    assign row = (row_calc < 4'd4) ? row_calc : 4'd0;\n    assign col = (col_calc < 4'd4) ? col_calc : 4'd0;\n    assign is_grey = (row & col) == 4'd0;\n\n    // Sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            current_diag <= 3'd0;\n            current_step <= 3'd0;\n            visit_count <= 16'd0;\n            grey_count <= 16'd0;\n            done <= 1'b0;\n            result <= 16'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= PROCESS;\n                        current_diag <= 3'd0;\n                        current_step <= 3'd0;\n                        visit_count <= 16'd0;\n                        grey_count <= 16'd0;\n                    end\n                end\n                \n                PROCESS: begin\n                    if (visit_count < K) begin\n                        visit_count <= visit_count + 16'd1;\n                        if (is_grey) grey_count <= grey_count + 16'd1;\n\n                        if (visit_count + 16'd1 == K) begin\n                            state <= DONE_ST;\n                        end else if (current_step == steps_current_diag - 1) begin\n                            current_step <= 3'd0;\n                            if (current_diag == 3'd6) state <= DONE_ST;\n                            else current_diag <= current_diag + 3'd1;\n                        end else begin\n                            current_step <= current_step + 3'd1;\n                        end\n                    end else begin\n                        state <= DONE_ST;\n                    end\n                end\n                \n                DONE_ST: begin\n                    result <= grey_count;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule